css:
:root {
    --color-background-primary: #0d0d12;
    --color-background-secondary: #16161d;
    --color-background-tertiary: #1f1f28;
    --color-background-info: #16202f;
    --color-background-danger: #2a1a1a;
    --color-background-success: #16241e;
    --color-background-warning: #2a2416;

    --color-text-primary: #eaeaef;
    --color-text-secondary: #a8a8b5;
    --color-text-tertiary: #8a8a96;
    --color-text-info: #7dabf8;
    --color-text-danger: #f28b82;
    --color-text-success: #7bd8a6;
    --color-text-warning: #f0c674;

    --color-border-primary: #2a2a35;
    --color-border-secondary: #34343f;
    --color-border-tertiary: #24242e;

    --font-sans:
        -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP',
        sans-serif;
    --font-serif: Georgia, 'Noto Serif JP', serif;
    --font-mono: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;

    --border-radius-md: 8px;
    --border-radius-lg: 12px;
    --border-radius-xl: 16px;

    --c-purple-100: #ede9fe;
    --c-purple-200: #ddd6fe;
    --c-purple-500: #8b5cf6;
    --c-purple-800: #5b21b6;
    --c-teal-100: #ccfbf1;
    --c-teal-200: #99f6e4;
    --c-teal-500: #14b8a6;
    --c-teal-800: #115e59;
    --c-coral-100: #ffe1da;
    --c-coral-200: #ffc7b8;
    --c-coral-500: #f9633b;
    --c-coral-800: #8f2f17;
    --c-pink-100: #fce7f3;
    --c-pink-200: #fbcfe8;
    --c-pink-500: #ec4899;
    --c-pink-800: #9d174d;
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: var(--font-sans);
    font-size: 16px;
    line-height: 1.7;
    font-weight: 400;
    background: var(--color-background-primary);
    color: var(--color-text-primary);
}

.app {
    display: flex;
    min-height: 100vh;
    align-items: flex-start;
}

.sidebar {
    flex: 0 0 260px;
    position: sticky;
    top: 0;
    height: 100vh;
    overflow-y: auto;
    padding: 28px 20px 40px;
    background: var(--color-background-secondary);
    border-right: 1px solid var(--color-border-primary);
}

.sidebar .brand {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 14px;
    font-weight: 500;
    color: var(--color-text-secondary);
    margin-bottom: 24px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--color-border-tertiary);
}
.sidebar .brand i {
    font-size: 18px;
    color: var(--color-text-info);
}

.sidebar nav a {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 10px;
    margin-bottom: 2px;
    border-radius: var(--border-radius-md);
    color: var(--color-text-secondary);
    text-decoration: none;
    font-size: 13px;
    line-height: 1.4;
}
.sidebar nav a:hover {
    background: var(--color-background-tertiary);
    color: var(--color-text-primary);
}
.sidebar nav a i {
    font-size: 15px;
    width: 16px;
    text-align: center;
    color: var(--color-text-tertiary);
}
.sidebar .nav-section-title {
    font-size: 11px;
    color: var(--color-text-tertiary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin: 18px 0 6px 10px;
}

.main {
    flex: 1;
    min-width: 0;
    padding: 48px 64px 96px;
}

.hero {
    padding-bottom: 32px;
    margin-bottom: 40px;
    border-bottom: 1px solid var(--color-border-primary);
}
.hero .eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: var(--color-text-info);
    background: var(--color-background-info);
    padding: 4px 10px;
    border-radius: var(--border-radius-md);
    margin-bottom: 16px;
}
.hero h1 {
    font-size: 30px;
    font-weight: 500;
    margin: 0 0 12px;
    line-height: 1.35;
}
.hero p.lead {
    font-size: 16px;
    color: var(--color-text-secondary);
    max-width: 780px;
    margin: 0 0 4px;
}
.hero .meta {
    font-size: 13px;
    color: var(--color-text-tertiary);
    margin-top: 16px;
}

h1 {
    font-size: 22px;
    font-weight: 500;
}
h2 {
    font-size: 18px;
    font-weight: 500;
    margin-top: 56px;
    margin-bottom: 16px;
    padding-top: 8px;
    display: flex;
    align-items: center;
    gap: 10px;
}
h2 i {
    color: var(--color-text-info);
    font-size: 20px;
}
h3 {
    font-size: 16px;
    font-weight: 500;
    margin-top: 32px;
    margin-bottom: 12px;
    color: var(--color-text-primary);
}
h4 {
    font-size: 14px;
    font-weight: 500;
    margin-top: 24px;
    margin-bottom: 8px;
    color: var(--color-text-secondary);
}
p {
    color: var(--color-text-secondary);
    margin: 0 0 14px;
}
strong {
    color: var(--color-text-primary);
    font-weight: 500;
}
a {
    color: var(--color-text-info);
}
code {
    font-family: var(--font-mono);
    font-size: 13px;
    background: var(--color-background-tertiary);
    padding: 2px 6px;
    border-radius: 4px;
    color: var(--color-text-warning);
}

section {
    margin-bottom: 8px;
}

.callout {
    display: flex;
    gap: 12px;
    background: var(--color-background-info);
    border: 1px solid var(--color-border-secondary);
    border-radius: var(--border-radius-lg);
    padding: 16px 18px;
    margin: 18px 0;
    font-size: 14px;
}
.callout i {
    color: var(--color-text-info);
    font-size: 18px;
    margin-top: 2px;
}
.callout p {
    margin: 0;
    color: var(--color-text-primary);
}

.callout.warning {
    background: var(--color-background-warning);
}
.callout.warning i {
    color: var(--color-text-warning);
}

table {
    width: 100%;
    border-collapse: collapse;
    margin: 18px 0 28px;
    font-size: 13.5px;
    background: var(--color-background-secondary);
    border-radius: var(--border-radius-md);
    overflow: hidden;
}
thead th {
    text-align: left;
    background: var(--color-background-tertiary);
    color: var(--color-text-primary);
    font-weight: 500;
    padding: 10px 14px;
    border-bottom: 1px solid var(--color-border-secondary);
    white-space: nowrap;
}
tbody td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--color-border-tertiary);
    color: var(--color-text-secondary);
    vertical-align: top;
}
tbody tr:last-child td {
    border-bottom: none;
}
tbody td code {
    white-space: nowrap;
}

.mermaid-wrap {
    text-align: center;
    background: var(--color-background-secondary);
    border: 1px solid var(--color-border-primary);
    border-radius: var(--border-radius-lg);
    padding: 28px 20px;
    margin: 20px 0 28px;
}
.mermaid-diagram svg {
    max-width: 100%;
    height: auto;
    display: block;
    margin: 0 auto;
    overflow: visible;
}
.diagram-caption {
    text-align: center;
    font-size: 12px;
    color: var(--color-text-tertiary);
    margin-top: 10px;
}
.diagram-error {
    color: var(--color-text-danger);
    font-size: 13px;
}

.step-card {
    display: flex;
    gap: 16px;
    padding: 18px 20px;
    background: var(--color-background-secondary);
    border: 1px solid var(--color-border-primary);
    border-radius: var(--border-radius-lg);
    margin-bottom: 14px;
}
.step-card .num {
    flex: 0 0 32px;
    height: 32px;
    border-radius: var(--border-radius-md);
    background: var(--color-background-tertiary);
    color: var(--color-text-info);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 500;
}
.step-card .body h4 {
    margin-top: 0;
    color: var(--color-text-primary);
    font-size: 15px;
}
.step-card .body p {
    margin-bottom: 0;
}

.ref-list {
    list-style: none;
    padding: 0;
    margin: 16px 0;
}
.ref-list li {
    padding: 10px 0;
    border-bottom: 1px solid var(--color-border-tertiary);
    font-size: 13.5px;
    color: var(--color-text-secondary);
}
.ref-list li:last-child {
    border-bottom: none;
}
.ref-list a {
    word-break: break-all;
}

.tag {
    display: inline-block;
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 20px;
    background: var(--c-purple-800);
    color: var(--c-purple-100);
    margin-right: 6px;
}
.tag.teal {
    background: var(--c-teal-800);
    color: var(--c-teal-100);
}
.tag.coral {
    background: var(--c-coral-800);
    color: var(--c-coral-100);
}

footer {
    margin-top: 64px;
    padding-top: 24px;
    border-top: 1px solid var(--color-border-primary);
    font-size: 12.5px;
    color: var(--color-text-tertiary);
}

@media (max-width: 900px) {
    .app {
        flex-direction: column;
    }
    .sidebar {
        position: relative;
        height: auto;
        width: 100%;
        flex: none;
    }
    .main {
        padding: 32px 20px 64px;
    }
}
